# owner: platform
"""Absence notices for parents, from attendance marks."""

from typing import List
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed

def check_owned(
    student: Student, marks: List[Mark]
) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark belongs to {mark.student_id}"
            )

def require_absences(missed: List[date]) -> None:
    if not missed:
        raise ProjectError("no absences to report")

def notice_text(student: Student, days: List[date]) -> str:
    """Wording for the notice, with dates oldest first."""
    listed = ", ".join(map(str, days))
    noun = "day" if len(days) == 1 else "days"
    return (
        f"{student.first_name} {student.last_name}"
        f" was absent {len(days)} {noun}: {listed}."
    )

def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    check_owned(student, marks)
    missed = days_missed(marks)
    require_absences(missed)
    return notice_text(student, missed)
